replace.new:
  // Browser print -> save as PDF. Handles Hebrew RTL natively,
  // no embedded fonts needed (ideal offline). The charts are redrawn with dark text first
  // (the on-screen colours are light and would be invisible on the white page), then restored.
  this.printing = true;
  this.renderCharts();
  const restore = () => { this.printing = false; this.renderCharts(); window.removeEventListener("afterprint", restore); };
  window.addEventListener("afterprint", restore);
  setTimeout(() => window.print(), 150);
},
